vulnerable_code:
#include <cstring>
#include <iostream>

void process(const char* data) {
    char buffer[64];
    // BAD: no bounds check, strcpy writes until it hits a null byte
    strcpy(buffer, data);
    std::cout << buffer << std::endl;
}

int main(int argc, char** argv) {
    if (argc > 1) process(argv[1]);
    return 0;
}

secure_code:
#include <string>
#include <iostream>

void process(const std::string& data) {
    // GOOD: std::string grows safely, no manual buffer arithmetic
    if (data.size() > 1024) {
        std::clog << "input too long\n";
        return;
    }
    std::cout << data << std::endl;
}

int main(int argc, char** argv) {
    if (argc > 1) process(argv[1]);
    return 0;
}
